// ---- chapter 28: two Regions -----------------------------------------
// Local: two Regions as a model in memory. No AWS.
"mr:demo": fresh("node scripts/demo.ts", { cwd: "examples/28-multi-region" }),
// The primary stack, in Tokyo. `mr:infra:synth` writes the templates of both stacks.
...infra("mr", "examples/28-multi-region", "AihMultiRegion"),
// The standby stack, in Osaka: deployed first, destroyed last.
"mr:standby:infra:diff": live(`${node} tools/src/infra/cdkd.ts diff examples/28-multi-region AihMultiRegionStandby`),
"mr:standby:infra:deploy": live(`${node} tools/src/infra/cdkd.ts deploy examples/28-multi-region AihMultiRegionStandby`),
"mr:standby:infra:destroy": live(`${node} tools/src/infra/cdkd.ts destroy examples/28-multi-region AihMultiRegionStandby`),
// Reads both Regions: replica status, replication rules, the health endpoints.
"mr:status": live("node --env-file-if-exists=../../.env scripts/mr.ts status", { cwd: "examples/28-multi-region" }),
// With --apply: edits one note in both Regions at once and reports which edit survived.
"mr:conflict": live("node --env-file-if-exists=../../.env scripts/mr.ts conflict", { cwd: "examples/28-multi-region" }),
// Counts the object versions in both buckets; --apply deletes them.
"mr:empty": live("node --env-file-if-exists=../../.env scripts/mr.ts empty", { cwd: "examples/28-multi-region" }),
